import subprocess
import re

# Map functions to files for context
func_to_file = {}
result = subprocess.run(["find", "src", "-name", "*.java"], capture_output=True, text=True)

for filepath in result.stdout.strip().split('\n'):
    if not filepath:
        continue
    with open(filepath, 'r') as f:
        content = f.read()
        # Extract package
        pkg_match = re.search(r'package\s+([\w.]+)', content)
        if pkg_match:
            # Extract all public methods
            methods = re.findall(r'(?:public|private|protected)\s+(?:static\s+)?[\w<>]+\s+(\w+)\s*\(', content)
            for method in methods:
                func_to_file[method] = filepath

# Key bridging functions to analyze
key_bridges = {
    "add": "REST → Service+Model",
    "delete": "REST → Service+Model", 
    "checkOutShoppingCart": "Service → Model",
    "checkout": "REST → Service",
    "applyCartItemPromotions": "Service → Model",
}

print("\n=== Primary Module Bridges ===\n")
print(f"{'Function':<30} {'Location':<50} {'Role':<40}")
print("-" * 120)

for func, role in key_bridges.items():
    file = func_to_file.get(func, "unknown")
    if file and file != "unknown":
        file_short = file.replace("src/main/java/com/redhat/coolstore/", "")
    else:
        file_short = "unknown"
    print(f"{func:<30} {file_short:<50} {role:<40}")

print("\n=== Cross-Module Call Counts ===\n")

# Get detailed call graph
result = subprocess.run(["rgctl", "relations", "--edge", "calls", "--format", "text"], 
                       capture_output=True, text=True)

bridges_detail = {
    "add": {"rest.CartEndpoint": set(), "service": set(), "model": set()},
    "checkOutShoppingCart": {"service.ShoppingCartService": set(), "model": set()},
    "applyCartItemPromotions": {"service.PromoService": set(), "model": set()},
}

for line in result.stdout.split('\n'):
    if ' -[calls]-> ' not in line:
        continue
    caller, called = line.split(' -[calls]-> ')

    for bridge_func in bridges_detail:
        if caller == bridge_func:
            if "Service" in called or "Service" in caller:
                key = "service"
            elif "Cart" in called or "Order" in called or "Product" in called:
                key = "model"
            else:
                key = "unknown"
            if key in bridges_detail[bridge_func]:
                bridges_detail[bridge_func][key].add(called)

for func, targets in bridges_detail.items():
    total = sum(len(v) for v in targets.values())
    print(f"{func}:")
    for module, funcs in targets.items():
        if len(funcs) > 0:
            print(f"  → {module:<30} calls {len(funcs)} functions")
